type Raw = typeof RAW;
const CATALOG = Object.fromEntries(
  Object.entries(RAW).map(([k, [en, nl, es, pt, de, fr]]) => [k, { en, nl, es, pt, de, fr }]),
) as { [K in keyof Raw]: I18nEntry };

export type UiKey = keyof Raw;
export const t = makeT(CATALOG);
export type T = (locale: Locale | string | null | undefined, key: UiKey, vars?: Record<string, string | number>) => string;
